  const origin = capture();
  const reply = await exchange({ action: "get", origin, port });
  if (reply.status !== "available" || typeof reply.ipc !== "string") {
    throw new Error(reply.message || "canonical port unavailable");
  }
  return decode(reply.ipc);
}

